# pets:fn:secretRoll; the answer is SAVED before "OK" (dsecretw.<word> = owed, dsecret.<word> = one per profile per word). The per-second
# tick gives it (part 3). The caller holds the record's io lock + its monitor.
M(sec, r"""
public static String clean(String s) {
  if (s == null) return "?";
  String t = s.replace('|', '/').replace('\\n', ' ').replace('\\r', ' ').trim();
  if (t.length() == 0) return "?";
  return t.length() > 60 ? t.substring(0, 60) : t;
}""")
M(sec, r"""
public static String requestLocked(@PKG@.PetRec r, int wi, String src, long now) {
  if (r == null || r.bad) return "BUSY";
  if (r.get("dsecret." + WORDS[wi]) != null) return "GIVEN";
  if (@PKG@.PetDragon.ownWhy(r, null) != null) return "HAS_DRAGON";
  if (@PKG@.PetDragon.hatcheryEgg(r) != null || r.keysWith("dsecretw.").length > 0) return "HAS_EGG";
  String s = clean(src);
  r.set("dsecretw." + WORDS[wi], EGGS[wi] + "|" + s + "|" + now + "|-1");
  r.set("dsecret." + WORDS[wi], "owed|" + now + "|" + s);
  if (!@PKG@.PetStore.save(r)) {
    r.set("dsecretw." + WORDS[wi], null);
    r.set("dsecret." + WORDS[wi], null);
    return "BUSY";
  }
  @PKG@.PetEgg.led(r, "secret-egg-owed " + WORDS[wi] + " egg=" + EGGS[wi] + " src=" + s, "secret");
  return "OK";
}""")
M(sec, r"""
public static String requestSync(@PKG@.PetRec r, int wi, String src, long now) {
  String c = null;
  synchronized (r) { c = requestLocked(r, wi, src, now); }
  return c;
}""")
