M(sfn, r"""
public Object apply(Object o) {
  try {
    if (!(o instanceof Object[])) return "BAD_PLAYER";
    Object[] a = (Object[]) o;
    if (a.length < 2) return "BAD_WORD";
    String src = a.length > 2 && a[2] != null ? String.valueOf(a[2]) : "?";
    return @PKG@.PetSecret.request(a[0], a[1] == null ? null : String.valueOf(a[1]), src, this.mode == 1);
  } catch (Throwable t) {
    @PKG@.PetsLog.warnOnce("secretfn:" + t.getClass().getName(), "pets:fn:giveSecretEgg failed (logged once): " + t);
    return "BUSY";
  }
}""")
